const safe = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,min,max,fallback=min)=>{const x=Number(v);return Number.isFinite(x)?Math.max(min,Math.min(max,Math.floor(x))):fallback};
const clone=o=>JSON.parse(JSON.stringify(o));
const initial={collection:clone(INITIAL_COLLECTION),favorite:'All',target:'Lightning',objective:'Balanced',rosterFilter:'All',rosterQuery:'',rosterOwned:false,onlyOwned:false,selected:'',teamNames:['','','',''],nav:'overview',compare:false,formFilter:'All',instances:[],teamEntries:[null,null,null,null],enemy1:'Water',enemy2:'',workshopName:'',workshopForm:'Basic',workshopUnit:'',plannerOwned:false};
function readState(){
 let previous=null,isV2=false;
 try{const raw=localStorage.getItem(STORAGE_V2);if(raw){previous=JSON.parse(raw);isV2=!!previous&&Array.isArray(previous.instances)}}catch{}
 if(!isV2){try{previous=JSON.parse(localStorage.getItem(STORAGE))}catch{}}
 if(!previous||typeof previous!=='object'||Array.isArray(previous))return clone(initial);
 const oldCollection=previous.collection&&typeof previous.collection==='object'&&!Array.isArray(previous.collection)?{...previous.collection}:{};
 const fixture=oldCollection.Fulmintis;
 if(fixture?.notes==='Imported from screenshots (27 Oct 2026).'&&fixture.level===60&&fixture.cp===3388&&fixture.star===6&&fixture.spent===22&&fixture.budget===43&&fixture.awaken?.ATK===20&&fixture.awaken?.REGEN===20&&fixture.held===''&&fixture.potential==='Perfect')delete oldCollection.Fulmintis;
 const instances=isV2?normalizeInstances(previous.instances):migrateLegacyCollection(oldCollection);
 const legacyTeam=Array.isArray(previous.teamNames)&&previous.teamNames.length===4?previous.teamNames:['','','',''];
 const entries=Array.isArray(previous.teamEntries)&&previous.teamEntries.length===4?previous.teamEntries:legacyTeam.map(species=>species?{species,form:'Basic'}:null);
 return {...clone(initial),...previous,instances,collection:collectionMirror(instances),teamEntries:entries,teamNames:legacyTeam,nav:'overview',rosterQuery:'',compare:false};
}
let state=readState(), modal=null, toastTimer;
