const owned=name=>state.instances.some(i=>i.species===name);
function persist(){
 state.instances=normalizeInstances(state.instances);
 state.collection=collectionMirror(state.instances);
 try{localStorage.setItem(STORAGE_V2,JSON.stringify({...state,nav:'overview',rosterQuery:'',compare:false}));}
 catch{flash('Browser storage unavailable. Export your Wildbook before closing.','warn')}
}
function flash(msg,type='info'){let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.textContent=msg;t.className='toast show '+type;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
