function avatar(a,size='md',formName=''){if(!a)return '<span class="avatar md">?</span>';let e=getElement(a.element);let picked=a.official?.forms.find(f=>f.name.toLowerCase()===String(formName).toLowerCase()||f.name.toLowerCase().startsWith(String(formName).toLowerCase())&&formName);const img=picked?.image||a.image||'';return `<span class="avatar ${size} ${img?'has-art':''}" style="--unit-color:${e.tone};--unit-symbol:'${e.symbol}'"><span class="avatar-halo"></span><span class="avatar-rune">${safe(e.symbol)}</span><span class="avatar-initial">${safe(a.monogram)}</span>${img?`<img src="${safe(img)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" alt="" onerror="this.style.display='none'">`:''}</span>`}
function unitCard(name,role,form,opts={}){const a=getAniimo(name)||{name,element:'Lightning',monogram:name.slice(0,2).toUpperCase(),role:role||'Support'};return `<button class="unit-card ${opts.compact?'compact':''}" data-open="${safe(name)}" aria-label="Open ${safe(name)} build"><div class="unit-visual">${avatar(a,opts.compact?'sm':'md',form)}<span class="unit-owned ${owned(name)?'yes':''}" title="${owned(name)?'Owned':'Not in collection'}">${owned(name)?icon('check',12):icon('plus',12)}</span></div><span class="unit-name">${safe(name)}</span><span class="unit-role">${safe(role||a.role)}${form&&form!=='Basic'?` · ${safe(form)}`:''}</span></button>`}
