function overview(){const researched=Object.keys(BUILDS).length;const picks=['Fire','Grass','Water'].map(id=>TEAMS.find(t=>t.element===id)).filter(Boolean);const features=[['workshop','01 / CRAFT','Build workshop','Make form-aware builds, compare held items and record your own copies.','spark'],['matchups','02 / COUNTER','Elemental matchups','Plan attacks and defenses across all nine elements and dual forms.','target'],['aniidex','03 / DISCOVER','Meet the entire Aniidex','Browse species, regional forms, Prismanas, skills and official artwork.','book'],['teams','04 / STRATEGIZE','Find your perfect team','Explore all nine elemental compositions and tactical alternatives.','team'],['progression','05 / EVOLVE','Grow with purpose','Plan held items, awakening priorities and Star Up investments.','spark']];const heroes=[['Glacy','Water','01'],['Stellarys','Dark','02'],['Scorchhowl','Fire','03']];return `<section class="cinematic-hero"><div class="hero-ambient" aria-hidden="true"></div><div class="hero-copy"><span class="cinema-eyebrow"><i></i> WELCOME TO YOUR NEXT ADVENTURE <span class="eyebrow-line"></span> EST. 2026</span><h1>Every little<br><span>wonder</span><br>is worth<br>discovering.</h1><p>Meet enchanting companions, discover their many forms, and find your own path through the world of Idyll.</p><div class="hero-buttons"><button class="btn primary" data-nav="aniidex">Meet the Aniimo ${icon('arrow',18)}</button><button class="btn outline" data-nav="teams">Build your team ${icon('arrow',18)}</button></div><div class="hero-footnote"><span class="signal-dot"></span><span>${catalog.mode==='live'?'New discoveries await':'Made for exploring · No account needed'}</span><span class="footnote-divider"></span><span>For curious Pathfinders</span></div></div><div class="hero-stage"><div class="stage-ring ring-one"></div><div class="stage-ring ring-two"></div><div class="stage-sigil" aria-hidden="true">ϟ</div>${heroes.map(([name,element,num],i)=>{const a=getAniimo(name);return `<button class="stage-creature figure-${i+1}" data-open="${safe(name)}" style="--figure-tone:${getElement(element).tone}" aria-label="Explore ${safe(name)}"><span class="stage-art">${avatar(a,'xl')}</span><span class="stage-label"><small>WILDBOOK / ${num}</small><b>${safe(name)}</b>${elBadge(element,true)}</span></button>`}).join('')}<div class="stage-coordinate">THE WILDBOOK / FIELD NOTES — 001</div></div><div class="hero-bottom-line"><span>TURN THE PAGE</span><span class="scroll-mark">↓</span><span>A WORLD OF POSSIBILITIES</span></div></section><section class="stats-ribbon" aria-label="Aniimo Center coverage"><div><strong>${catalog.items.length||ANIIMO.length}<span>+</span></strong><small>ANIIMO INDEXED</small></div><div><strong>${TEAMS.length.toString().padStart(2,'0')}</strong><small>ELEMENTAL PATHS</small></div><div><strong>${ITEMS.length.toString().padStart(2,'0')}</strong><small>HELD ITEMS</small></div><div><strong>${researched.toString().padStart(2,'0')}</strong><small>BUILD GUIDES</small></div><button class="ribbon-link" data-nav="aniidex">MEET YOUR COMPANIONS ${icon('arrow',17)}</button></section><section class="experience-section"><div class="experience-heading"><div><span class="section-kicker">START YOUR JOURNEY</span><h2>One world. <em>Endless possibilities.</em></h2><p>From your very first companion to an endgame squad, find inspiration for every step.</p></div><span class="section-index">01 — 03</span></div><div class="feature-paths">${features.map(([id,number,heading,desc,ic])=>`<button class="feature-path" data-nav="${id}"><span class="path-top"><span>${number}</span>${icon(ic,25)}</span><span class="path-content"><strong>${heading}</strong><small>${desc}</small></span><span class="path-link">EXPLORE ${icon('arrow',17)}</span></button>`).join('')}</div></section><section class="experience-section elements-section"><div class="experience-heading"><div><span class="section-kicker">NINE ELEMENTAL PATHS</span><h2>Nine paths to <em>power.</em></h2><p>Choose an element to uncover its lineup, combat philosophy and alternatives.</p></div>${button('Browse all compositions','teams','btn outline')}</div><div class="element-gallery">${ELEMENTS.map(e=>`<button class="element-portrait" data-team="${safe(e.id)}" style="--tile:${e.tone}"><span class="element-portrait-glow"></span><span class="element-big-symbol">${e.symbol}</span><span class="element-details"><strong>${safe(e.id)}</strong><small>EXPLORE ELEMENT ${icon('arrow',14)}</small></span></button>`).join('')}</div></section><section class="experience-section spotlight-section"><div class="experience-heading"><div><span class="section-kicker">STRATEGY SPOTLIGHT</span><h2>Squads worth <em>discovering.</em></h2><p>Explore team combinations, swap companions, and find a strategy that fits your journey.</p></div>${button('Open team lab','teams','btn outline')}</div><div class="spotlight-grid">${picks.map(teamPreview).join('')}</div></section><section class="experience-cta"><div><span class="section-kicker">YOUR ADVENTURE, YOUR WAY</span><h2>Make every upgrade <em>count.</em></h2><p>Track your collection on this device. No account needed — your progress stays with you.</p></div><div><button class="btn primary" data-nav="collection">Open my collection ${icon('arrow',17)}</button><button class="btn outline" data-nav="planner">Build a team ${icon('arrow',17)}</button></div></section>`}

function teamsPage(){const current=TEAMS.find(t=>t.element===state.target)||TEAMS[0];const e=getElement(current.element);const line=current.lineup;const own=line.filter(r=>owned(r[0])).length;return `${title('TEAM ARCHITECT / 002','Elemental <em>team lab.</em>','Explore nine researched compositions, role coverage, substitutions, and proven rotation ideas.',button('Build custom squad','planner','btn primary'))}<div class="filter-head"><div class="filter-label">SELECT YOUR ELEMENT <span>09 TYPES</span></div><div class="elements-strip">${ELEMENTS.map(ele=>`<button data-team="${ele.id}" class="element-switch ${current.element===ele.id?'chosen':''}" style="--tile:${ele.tone}"><span>${ele.symbol}</span>${ele.id}</button>`).join('')}</div></div><div class="team-detail" style="--team-tone:${e.tone}"><div class="detail-background"></div><div class="detail-main"><div class="detail-overline">${elBadge(e.id)} <span>• ${safe(current.tag)}</span></div><h2>${safe(current.name)}</h2><p class="team-summary">${safe(current.summary)}</p><div class="team-measures"><span>${icon('team',16)} 4-MEMBER SQUAD</span><span>${icon('check',16)} ${own}/4 IN COLLECTION</span><span>${icon('book',16)} TEAM GUIDE</span></div><div class="team-row">${line.map(([name,role,form])=>unitCard(name,role,form)).join('')}</div><div class="team-detail-actions"><button class="btn primary" data-load-team="${current.element}">${icon('layers',17)} Load in planner</button><button class="btn secondary" data-team-owned="${current.element}">${icon('plus',17)} Mark lineup owned</button></div></div><aside class="detail-why"><div class="detail-aside-title">WHY IT WORKS</div>${current.strength.map((x,i)=>`<div class="plus-row"><span class="small-plus">0${i+1}</span><span>${safe(x)}</span></div>`).join('')}<div class="tactical-callout"><span>TACTICAL CONSIDERATION</span><p>${safe(current.risk)}</p></div><div class="owned-bar"><div><span>ROSTER READINESS</span><strong>${Math.round(own/4*100)}%</strong></div><div class="progress"><i style="width:${own/4*100}%"></i></div><small>${own} of 4 team members owned</small></div></aside></div><div class="secondary-grid"><section class="content-card"><div class="card-head"><span class="section-kicker">COMBAT FLOW</span><h3>Suggested rotation</h3></div><div class="rotation-list">${current.rotation.map((s,i)=>`<div class="rotation-step"><span>${String(i+1).padStart(2,'0')}</span><p>${safe(s)}</p></div>`).join('')}</div><div class="hint-block">${icon('spark',18)} <span>${safe(current.tip)}</span></div></section><section class="content-card"><div class="card-head"><span class="section-kicker">ADAPT YOUR SQUAD</span><h3>Recommended alternatives</h3></div><div class="alternatives">${current.alternatives.map(alt=>`<div class="alternative"><div class="alt-compare">${avatar(getAniimo(alt.out),'sm')}<span>${safe(alt.out)}</span>${icon('arrow',17)}${avatar(getAniimo(alt.in),'sm')}<strong>${safe(alt.in)}</strong></div><p>${safe(alt.why)}</p><button data-swap="${safe(current.element)}|${safe(alt.out)}|${safe(alt.in)}|${safe(alt.form)}" class="text-action">Load alternative ${icon('arrow',14)}</button></div>`).join('')}</div><div class="subnote">These recommendations are situation-dependent, not universally strongest.</div></section></div>`}
function isPrismana(a){return a.official?.forms?.some(f=>/prismana/i.test(f.name))}
function variants(a){return a.official?.forms || []}
function filterAniimo(){const q=state.rosterQuery.trim().toLowerCase();return ANIIMO.filter(a=>{
 const fs=variants(a);
 const elementMatch=state.rosterFilter==='All'||a.element===state.rosterFilter||fs.some(f=>f.elements.includes(state.rosterFilter));
 const formMatch=state.formFilter==='All'||state.formFilter==='Prismana'&&isPrismana(a)||state.formFilter==='Multiple'&&fs.length>1||state.formFilter==='Basic'&&fs.length===1;
 const text=[a.name,a.official?.id,a.official?.portuguese,...fs.map(f=>f.name),...fs.flatMap(f=>f.habitats)].filter(Boolean).join(' ').toLowerCase();
 return elementMatch&&formMatch&&(!state.rosterOwned||owned(a.name))&&(!q||text.includes(q));
});}
function catalogNotice(){if(catalog.mode==='loading')return `<span class="live-state"><i></i> DISCOVERING COMPANIONS...</span>`;
 if(catalog.mode==='live'||catalog.mode==='cached')return `<span class="live-state good"><i></i> ${catalog.items.length} COMPANIONS TO MEET</span>`;
 if(catalog.mode==='offline')return `<span class="live-state"><i></i> YOUR SAVED WILDBOOK</span>`;
 return `<span class="live-state"><i></i> ${ANIIMO.length} COMPANIONS TO EXPLORE</span>`;}
function library(){const units=filterAniimo();const formCount=catalog.items.reduce((n,a)=>n+a.forms.length,0);const prismana=catalog.items.filter(x=>x.forms.some(f=>/prismana/i.test(f.name))).length;
 return `${title('YOUR ANIIDEX / EXPLORE','Meet the <em>Aniimo.</em>','Find your next favorite companion. Explore forms, elements, abilities, habitats and more.',`<button class="btn secondary" data-action="refresh-dex">${icon('refresh',16)} Check for discoveries</button> ${button('Team lab','teams','btn primary')}`)}
 <section class="dex-status content-card wildbook-summary"><div><div class="section-kicker">YOUR WORLD OF WONDERS</div><div class="dex-status-main">${catalogNotice()}<p>Every companion has its own story. Open a portrait to explore the forms, skills and surprises waiting inside.</p></div></div><div class="dex-metrics"><div><strong>${catalog.items.length||ANIIMO.length}</strong><span>Companions</span></div><div><strong>${formCount||'—'}</strong><span>Forms to discover</span></div><div><strong>${prismana||'—'}</strong><span>Prismana</span></div></div></section>
 <section class="library-toolbar live-toolbar"><label class="search-wrap">${icon('search',19)}<input id="roster-search" type="search" placeholder="Name, number, form or habitat..." value="${safe(state.rosterQuery)}" aria-label="Search Aniimo"></label><label class="select-wrap">ELEMENT <select id="roster-element"><option value="All">All elements</option>${ELEMENTS.map(e=>`<option value="${e.id}" ${state.rosterFilter===e.id?'selected':''}>${e.id}</option>`).join('')}</select></label><label class="select-wrap">FORM <select id="roster-form"><option value="All" ${state.formFilter==='All'?'selected':''}>Any form</option><option value="Prismana" ${state.formFilter==='Prismana'?'selected':''}>Has Prismana</option><option value="Multiple" ${state.formFilter==='Multiple'?'selected':''}>Multiple forms</option><option value="Basic" ${state.formFilter==='Basic'?'selected':''}>Single form</option></select></label><button class="toggle-filter ${state.rosterOwned?'on':''}" data-toggle="roster-owned">${icon('check',16)} Owned only</button></section>
 <div class="library-summary"><span><b>${units.length}</b> of ${ANIIMO.length} Aniimo shown</span><span><b>${Object.keys(BUILDS).length}</b> researched build profiles</span><span>${catalog.mode==='loading'?'Discovering more forms...':'Discover forms, skills and traits inside each companion profile'}</span></div>
 <div class="library-grid dex-grid">${units.map(a=>{const b=getBuild(a),forms=variants(a),e=getElement(a.element);return `<article class="library-card dex-card" style="--card-element:${e.tone}"><button class="library-open" data-open="${safe(a.name)}" aria-label="Explore ${safe(a.name)} forms and abilities"><span class="dex-card-wash"></span><span class="card-topline"><span>${a.official?`NO. ${safe(a.official.id)}`:'WILDBOOK'}</span>${isPrismana(a)?'<span class="dex-prismana">✦ PRISMANA</span>':''}</span><span class="dex-art-wrap">${avatar(a,'lg')}</span><span class="dex-card-title"><span class="dex-card-element">${elBadge(a.element,true)}</span><strong>${safe(a.name)}</strong><small>${safe(a.role)} · ${forms.length?`${forms.length} ${forms.length===1?'form':'forms'}`:'Forms unverified'}</small></span></button><div class="dex-card-bottom"><span>${b.quality.startsWith('Role')?'BUILD IDEA':'BUILD GUIDE'}</span><button class="dex-card-open" data-open="${safe(a.name)}" aria-label="Open ${safe(a.name)} details">${icon('arrow',18)}</button></div></article>`}).join('')}</div>`;}

function itemsPage(){return `${title('EQUIPMENT CODEX / 004','Held item <em>lab.</em>','Compare published item effects and role fit. BIS recommendations require checking each Aniimo\'s actual kit.',button('Open build library','aniidex','btn primary'))}<div class="gear-callout">${icon('info',20)}<div><strong>15 documented items, not 15 universal best-in-slot answers.</strong><p>Choose equipment that suits your companion’s role and abilities. Some ideas are general starting points rather than proven best-in-slot combinations.</p></div></div><div class="item-grid">${ITEMS.map((item,i)=>`<article class="item-card"><div class="item-icon">${icon(item.main==='BREAK'?'shield':item.main==='HP'?'heart':item.main==='REGEN'?'refresh':'spark',25)}</div><span class="item-index">GEAR / ${String(i+1).padStart(2,'0')}</span><h3>${safe(item.name)}</h3><span class="item-main">${safe(item.main)}</span><p>${safe(item.effect)}</p><div class="item-roles"><small>BEST-FIT ROLE</small><strong>${safe(item.focus)}</strong></div><div class="item-rec">${icon('info',14)} ${safe(item.recommend)}</div></article>`).join('')}</div><section class="content-card item-guidance"><div><span class="section-kicker">EQUIPMENT STRATEGY</span><h3>How to pick the real best item</h3></div><p>Compare three factors: whether its passive triggers with your equipped skills, whether its stat scales your actual role, and whether it helps the full four-member rotation. A +15 passive may change the ranking. Equip your selected item in My Collection to record your setup.</p>${button('Open collection','collection','btn secondary')}</section>`}
function progression(){if(!state.selected||!getAniimo(state.selected)){return `${title('ASCENSION PATH / 005','Upgrade <em>roadmap.</em>','Select any Aniimo to review role priorities, build-specific advice, stat breakpoints, and Star Up planning.',button('Explore build library','aniidex','btn secondary'))}<div class="roadmap-top"><div><span class="section-kicker">CHOOSE YOUR TARGET</span><h2>Which Aniimo are you upgrading?</h2></div><label class="select-wrap large">SELECT ANIIMO<select id="progress-select"><option value="" selected>Choose an Aniimo...</option>${ANIIMO.map(u=>`<option value="${safe(u.name)}">${safe(u.name)}${owned(u.name)?' ✓':''}</option>`).join('')}</select></label></div><div class="empty-state upgrade-empty">${icon('spark',32)}<h3>Your next upgrade starts here</h3><p>Pick any entry in the selector above. No Aniimo or stats are preselected — your own roster stays yours.</p><button class="btn primary" data-nav="aniidex">${icon('book',16)} Browse Aniimo builds</button></div><div class="field-note">${icon('info',20)}<p>General stat priorities are starting points, not guarantees. Verify each creature’s actual skill scaling and current patch before spending rare awakening resources.</p></div>`;}const name=state.selected;const a=getAniimo(name),b=getBuild(a),role=ROLE_PRIORITIES[a.role],r=state.collection[name],lv=r?.level||0,star=r?.star||0,budget=r?.budget||0,spent=r?.spent||0,avail=Math.max(0,budget-spent);const major=b.stats.filter(x=>STAT_NAMES.includes(x));const next=major.find(x=>(r?.awaken?.[x]??0)<20);const nextVal=next?(r?.awaken?.[next]??0):null;const milestone=nextVal!==null?[4,8,12,16,20].find(v=>v>nextVal):null;return `${title('ASCENSION PATH / 005','Upgrade <em>roadmap.</em>','Prioritize irreversible awakenings, plan star-up gates and avoid investing materials based on unverified assumptions.',button('Open full profile','aniidex','btn secondary'))}<div class="roadmap-top"><div><span class="section-kicker">TARGET ANIIMO</span><h2>Ascension planning</h2></div><label class="select-wrap large">SELECT PROFILE<select id="progress-select">${ANIIMO.map(u=>`<option value="${safe(u.name)}" ${name===u.name?'selected':''}>${safe(u.name)}${owned(u.name)?' ✓':''}</option>`).join('')}</select></label></div><div class="progression-intro" style="--progress-tone:${getElement(a.element).tone}">${avatar(a,'xl')}<div class="progress-intro-copy"><div>${elBadge(a.element)} <span class="role-badge">${safe(a.role)}</span></div><h2>${safe(name)}</h2><p>${safe(b.notes)}</p><button class="text-action" data-open="${safe(name)}">View individual build & edit stats ${icon('arrow',16)}</button></div><div class="budget-figure"><span>AWAKENINGS AVAILABLE</span><strong>${owned(name)?avail:'—'}</strong><small>${owned(name)?`${spent} used / ${budget} budget`:'Add to your collection to personalize'}</small></div></div><div class="roadmap-grid"><section class="content-card"><span class="section-kicker">INVESTMENT QUEUE</span><h3>Prioritize these attributes</h3><div class="stat-priority-stack">${b.stats.map((st,i)=>`<div class="priority-point"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${safe(st)}</strong><p>${i===0?'Primary role scaling':i===1?'Secondary role efficiency':'Individual trait-dependent choice'}</p></div><span>${STAT_NAMES.includes(st)&&owned(name)?safe(String(r.awaken?.[st]??0))+'/20':'CHECK KIT'}</span></div>`).join('')}</div><div class="hint-block">${icon('info',17)}<span>${safe(b.third)} ${safe(role.avoid)}</span></div>${owned(name)?`<div class="planned-next"><span class="section-kicker">NEXT INVESTMENT</span><p>${next&&milestone?`Consider ${safe(next)} toward total Potential ${milestone}. Confirm star bonuses and actual in-game point cost.`:'Primary documented priorities are complete. Preserve remaining points until a specific encounter or trait justifies a third stat.'}</p></div>`:''}</section><section class="content-card"><span class="section-kicker">STAR UP CHECKLIST</span><h3>Verify each unlock per Aniimo</h3><div class="star-track">${[{label:'CURRENT STAR',desc:'Record your actual Star Up level.',value:owned(name)?String(star):'—'},{label:'LEVEL REQUIREMENT',desc:'Check the next Star Up level gate in game.',value:'CHECK'},{label:'MATERIAL REQUIREMENTS',desc:'Check the required items and quantities in game.',value:'CHECK'},{label:'AWAKENING CAPACITY',desc:'Record the new cap after Star Up in your profile.',value:owned(name)?String(budget):'—'}].map(x=>`<div class="star-milestone"><span>${icon('spark',17)}</span><div><strong>${x.label}</strong><small>${x.desc}</small></div><b>${x.value}</b></div>`).join('')}</div><div class="tiny-advisory">${icon('alert',17)} The cited tests report that awakening resets are unavailable above level 60. Verify the latest rules before leveling past this point.</div></section></div><section class="content-card breakpoint-card"><span class="section-kicker">BREAKPOINT INTELLIGENCE</span><h3>Spend in meaningful steps</h3><p>Based on the cited test data, total Potential bonuses are larger at the fourth-point intervals. Star-up bonuses can shift the number of purchased points required. Always read the total displayed in game.</p><div class="breakpoint-row">${[4,8,12,16,20].map(x=>`<span>${x}<small> TOTAL</small></span>`).join('')}</div><div class="sources-foot"><span class="muted">Always verify the current in-game awakening rules before investing.</span></div></section>`}
function personalPanel(name){return `<div class="wb-dossier-footer"><div><span class="section-kicker">MAKE THIS BUILD YOURS</span><h3>Your own copies, forms and equipment</h3><p>Open the Workshop to compare variants, save multiple companions of one species, and plan personal awakening investments.</p></div><button class="btn primary" data-workshop-name="${safe(name)}">Open build workshop ${icon('arrow',16)}</button></div>`;}
function formCompare(a,current){const basic=a.official?.forms.find(f=>/^basic$/i.test(f.name))||a.official?.forms[0];if(!basic||basic.id===current.id)return '';
 const shared=['HP','ATK','BREAK','P.DEF','M.DEF','REGEN'];const delta=shared.map(st=>({stat:st,value:(basic.stats?.[st]!=null&&current.stats?.[st]!=null)?current.stats[st]-basic.stats[st]:null}));
 const gained=current.elements.filter(x=>!basic.elements.includes(x));const lost=basic.elements.filter(x=>!current.elements.includes(x));
 return `<div class="dex-comparison"><div class="section-kicker">FORM COMPARISON / VS BASIC</div><h4>${safe(current.name)} changes</h4><div class="dex-element-delta"><span>Basic: ${safe(basic.elements.join(' + ')||'Unknown')}</span><span>Selected: ${safe(current.elements.join(' + ')||'Unknown')}</span></div>${gained.length||lost.length?`<p class="dex-delta-caption">${gained.length?'Gains '+safe(gained.join(' / '))+' element':''}${gained.length&&lost.length?' · ':''}${lost.length?'Loses '+safe(lost.join(' / '))+' element':''}</p>`:''}<div class="dex-delta-grid">${delta.map(d=>`<div class="dex-delta ${d.value>0?'up':d.value<0?'down':''}"><small>${safe(d.stat)}</small><strong>${d.value===null?'—':d.value===0?'0':(d.value>0?'+':'')+d.value}</strong></div>`).join('')}</div><small>Base attribute differences only. They are not a calculation of final combat DPS, skill scaling, or build quality.</small></div>`;
}
function officialDetail(a) {
 const o=a?.official;if(!o)return `<div class="dex-unavailable">This companion’s form details are still being discovered. Explore another one or check for discoveries again.</div>`;
 const forms=o.forms||[];const chosen=activeFormByName.get(a.name);const f=forms.find(x=>x.id===chosen)||forms[0];
 const statNames=['HP','ATK','BREAK','P.DEF','M.DEF','REGEN'];
 const statblock=f.stats?`<div class="dex-statgrid">${statNames.map(k=>`<div class="dex-stat"><small>${safe(k)}</small><strong>${f.stats[k]===null?'—':safe(f.stats[k])}</strong></div>`).join('')}<div class="dex-stat total"><small>BASE TOTAL</small><strong>${f.stats.total??'—'}</strong></div></div>`:'<p class="muted">Attribute values are not published for this form.</p>';
 const skillblock=f.skills.length?`<div class="dex-skill-list">${f.skills.map(sk=>`<div class="dex-skill"><div><strong>${safe(sk.name)}</strong><span>${safe([sk.type,...sk.element].filter(Boolean).join(' · '))}</span></div><div class="dex-skill-numbers">${sk.power!=null?`POWER ${safe(sk.power)}`:''}${sk.cost!=null?` · COST ${safe(sk.cost)}`:''}</div>${sk.description?`<p>${safe(sk.description)}</p>`:''}</div>`).join('')}</div>`:'<p class="muted">No published skills for this form in the current feed.</p>';
 return `<section class="dex-official"><div class="dex-official-head"><div><div class="section-kicker">COMPANION NO. ${safe(o.id)}</div><h3>${safe(a.name)} · Full form encyclopedia</h3><p>Discover the details of every documented form, from elements to skills and traits.</p></div></div>
 <div class="dex-form-tabs" role="group" aria-label="Choose Aniimo form">${forms.map(fm=>`<button data-form-name="${safe(a.name)}" data-form-id="${safe(fm.id)}" class="dex-form-tab ${fm.id===f.id?'active':''}">${safe(fm.name)}</button>`).join('')}</div>
 <div class="dex-form-detail"><div class="dex-form-portrait">${f.image?`<img src="${safe(f.image)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" alt="${safe(a.name+' — '+f.name)}" onerror="this.style.display='none'">`:avatar(a,'xl')}<div class="dex-form-caption">${safe(f.name)}${f.stage?` · STAGE ${f.stage}`:''}</div></div><div class="dex-form-attributes"><div class="dex-form-badges">${f.elements.map(x=>elBadge(x,true)).join('')} ${f.roles.map(x=>`<span class="role-badge">${safe(x)}</span>`).join('')}</div><p>${safe(f.description||o.description||'No description supplied for this form.')}</p>${statblock}</div></div>
 ${formCompare(a,f)}<h3 class="sheet-section">Skills · ${f.skills.length}</h3>${skillblock}
 <h3 class="sheet-section">Traits · ${f.traits.length}</h3>${f.traits.length?`<div class="dex-traits">${f.traits.map(t=>`<div><strong>${safe(t.name)}</strong>${t.description?`<p>${safe(t.description)}</p>`:''}</div>`).join('')}</div>`:'<p class="muted">No traits reported for this form.</p>'}
 <div class="dex-facts"><div><strong>HABITATS</strong><p>${safe(f.habitats.join(' · ')||'Not published')}</p></div><div><strong>EVOLUTION TARGETS</strong><p>${safe(o.evolution.join(' · ')||'Not published')}</p></div></div></section>`;
}
function buildDetail(name){const a=getAniimo(name);if(!a)return '';const b=getBuild(a),record=state.collection[name],r=ROLE_PRIORITIES[a.role]||ROLE_PRIORITIES.Support;const count=a.official?.forms?.length||0;return `<div class="build-overlay" data-close="modal"><section class="build-sheet" role="dialog" aria-modal="true" aria-label="${safe(name)} field guide"><div class="sheet-bar"><span><span class="modal-serial">Aniimo Wildbook</span> / BUILD IDEA / ${safe(a.name).toUpperCase()}</span><button class="close-btn" data-close="modal" aria-label="Close Aniimo details">${icon('x',22)}</button></div><div class="dossier-layout"><aside class="dossier-poster" style="--sheet-tone:${getElement(a.element).tone}"><div class="poster-halo"></div><div class="poster-orbit"></div><span class="poster-overline">COMPANION PROFILE <span>/${safe(a.official?.id||'—')}</span></span><div class="poster-art">${avatar(a,'xl')}</div><div class="poster-caption">${elBadge(a.element)} <span>${safe(a.role)}</span></div><h2>${safe(a.name)}</h2><p>${count?`${count} documented ${count===1?'form':'forms'} · `:''}${safe(b.quality)}</p><button class="btn primary" data-workshop-name="${safe(name)}">${icon('spark',16)} Explore forms & track your copies</button><small class="poster-legal">Your companions, your adventure.</small></aside><div class="sheet-scroll"><div class="dossier-intro"><span class="section-kicker">THE WILDBOOK / EVERY FORM</span><h3>Explore every <em>side.</em></h3><p>Discover a companion’s forms, abilities, elements, habitats and growth paths. Every form has a story to tell.</p></div>${officialDetail(a)}<section class="dossier-build"><span class="section-kicker">GROW TOGETHER</span><h3 class="sheet-section">Your <em>build guide.</em></h3><p class="sheet-intro">${safe(b.notes)}</p><div class="build-facts"><div><small>HELD ITEM</small><strong>${safe(b.item)}</strong><span>Alternative: ${safe(b.altItem)}</span></div><div><small>AWAKENING ORDER</small><strong>${safe(b.stats.join(' → '))}</strong><span>${safe(b.third)}</span></div><div><small>PERSONALITY</small><strong>${safe(b.personality)}</strong><span>${safe(b.form)}</span></div><div><small>ACTIVE SKILLS</small><strong>${b.skills.length?b.skills.map(safe).join(' + '):'Not individually verified'}</strong><span>${b.innate?'Innate: '+safe(b.innate):'Check current in-game loadout'}</span></div></div><h3 class="sheet-section">Battle plan</h3><p class="detail-description">${safe(b.rotation)}</p><h3 class="sheet-section">Investment priorities</h3><div class="policy-line">${icon('chart',18)}<p>${safe(r.explain)} <strong>${safe(r.avoid)}</strong></p></div></section>${personalPanel(name)}</div></div></section></div>`}

// Transparency-focused checklist; it is not a computed DPS, win rate, or performance prediction.
function gradeTeam(names){const selected=names.map(getAniimo).filter(Boolean);const ref=TEAMS.find(t=>t.element===state.target);const roles=selected.map(a=>ref?.lineup.find(([name])=>name===a.name)?.[1]||a.role);const uniq=new Set(selected.map(a=>a.name));let issues=[];let pts=0;if(roles.includes('DPS'))pts+=20;else issues.push('No primary DPS');if(roles.includes('Break'))pts+=20;else issues.push('No dedicated breaker (some supports can BREAK)');if(roles.includes('Regen'))pts+=20;else issues.push('No REGEN role');if(roles.includes('Heal'))pts+=15;else issues.push('No dedicated healer');if(roles.includes('Support'))pts+=10;else issues.push('No explicit support role');pts+=Math.round(selected.length/4*10);if(uniq.size!==selected.length){issues.push('Duplicate Aniimo selected');pts=Math.max(0,pts-15)}let own=selected.filter(a=>owned(a.name)).length;pts+=Math.round(own/4*5);return {pts:Math.min(100,pts),issues,selected,own}}
function planner(){let lineup=state.teamNames.map(n=>n||'');let current=gradeTeam(lineup);const rec=TEAMS.find(t=>t.element===state.target)||TEAMS[0];return `${title('BUILD ENGINE / 004','Squad <em>optimizer.</em>','Plan a four-Aniimo composition, check roles and ownership, then compare it with research-backed team templates.',button('Discover Aniimo','aniidex','btn subtle','book'))}<div class="planner-head"><div><span class="section-kicker">SQUAD BUILDER</span><h2>Forge your four-member team</h2><p>Composition health scores reflect roles and collection readiness — not predicted combat damage.</p></div><div class="select-wrap large"><label for="team-preset">TEAM PRESET</label><select id="team-preset">${TEAMS.map(t=>`<option value="${t.element}" ${t.element===state.target?'selected':''}>${t.element} · ${t.name}</option>`).join('')}</select></div></div><div class="planner-layout"><div><section class="planner-canvas"><div class="planner-top"><span>ACTIVE SQUAD <i>4 SLOTS</i></span><button class="mini-link" data-load-team="${state.target}">${icon('refresh',15)} Load ${safe(state.target)} recommendation</button></div><div class="planner-slots">${[0,1,2,3].map((i)=>{const name=lineup[i],a=getAniimo(name),el=a?getElement(a.element):null;return `<div class="planner-slot"><div class="slot-top"><span>0${i+1} / ${['CARRY','SUPPORT','UTILITY','FLEX'][i]}</span>${name&&owned(name)?'<span class="slot-owned">OWNED</span>':''}</div><div class="slot-avatar">${a?avatar(a,'lg'):`<span class="slot-empty">${icon('plus',30)}</span>`}</div><select class="slot-select" data-slot="${i}" aria-label="Select team slot ${i+1}"><option value="">Select Aniimo...</option>${ANIIMO.map(u=>`<option value="${safe(u.name)}" ${name===u.name?'selected':''}>${safe(u.name)}${owned(u.name)?' ✓':''}</option>`).join('')}</select>${a?`<div class="slot-roles">${elBadge(a.element,true)} <span>${safe(a.role)}</span></div>`:`<div class="slot-roles">OPEN SLOT</div>`}</div>`}).join('')}</div><div class="planner-actions"><button class="btn primary" data-analyze="team">${icon('chart',17)} Analyze composition</button><button class="btn secondary" data-clear="team">${icon('refresh',16)} Reset squad</button></div></section><section class="content-card tactical-panel"><span class="section-kicker">TEAM INSPIRATION</span><h3>${safe(rec.name)}</h3><p>${safe(rec.summary)}</p><div class="horizontal-members">${rec.lineup.map(([name,role])=>`<div>${avatar(getAniimo(name),'sm')}<span><strong>${safe(name)}</strong><small>${safe(role)}</small></span></div>`).join('')}</div><button class="text-action" data-team="${safe(rec.element)}">See full ${safe(rec.element)} strategy ${icon('arrow',15)}</button></section></div><div><div class="analysis-card"><div class="analysis-head"><span class="section-kicker">COMPOSITION CHECKLIST</span><span class="heuristic-badge">HEURISTIC</span></div><div class="analysis-score"><div class="score-ring" style="--score:${current.pts}"><div><strong>${current.pts}</strong><span>/100</span></div></div><div><h3>${current.pts>=80?'Well-rounded roles':current.pts>=55?'Some role gaps':'Needs revision'}</h3><p>Role coverage + owned readiness</p></div></div><div class="analysis-divider"></div><div class="analysis-row"><span>DPS carry</span><strong class="${current.selected.some(a=>a.role==='DPS')?'positive':'negative'}">${current.selected.some(a=>a.role==='DPS')?'COVERED':'MISSING'}</strong></div><div class="analysis-row"><span>BREAK</span><strong class="${current.selected.some(a=>a.role==='Break')?'positive':'negative'}">${current.selected.some(a=>a.role==='Break')?'COVERED':'REVIEW'}</strong></div><div class="analysis-row"><span>Energy / REGEN</span><strong class="${current.selected.some(a=>a.role==='Regen')?'positive':'negative'}">${current.selected.some(a=>a.role==='Regen')?'COVERED':'MISSING'}</strong></div><div class="analysis-row"><span>Healing</span><strong class="${current.selected.some(a=>a.role==='Heal')?'positive':'negative'}">${current.selected.some(a=>a.role==='Heal')?'COVERED':'OPTIONAL'}</strong></div><div class="analysis-row"><span>Owned members</span><strong>${current.own} / 4</strong></div><div class="analysis-alert">${icon('alert',18)}<span>${current.issues.length?safe(current.issues[0]):'All major checklist criteria covered. Confirm elemental weaknesses manually.'}</span></div><p class="analysis-disclaimer">This is a transparent composition checklist, not a DPS simulator. Team forms can change combat roles and elemental coverage.</p></div><div class="content-card about-awakening"><span class="section-kicker">UPGRADE INTELLIGENCE</span><h3>Maximize your resources</h3><p>Role-first investment, then specific skill scaling. Stat breakpoints commonly occur at total Potential 4, 8, 12, 16 and 20.</p><div class="priority-list">${[['DPS','ATK → REGEN'],['BREAK','BREAK → REGEN'],['REGEN','REGEN'],['HEAL','HP'],['SUPPORT','Trait-dependent']].map(([role,prio])=>`<div><span>${role}</span><strong>${prio}</strong></div>`).join('')}</div><div class="tiny-advisory">${icon('info',17)} Reset restrictions above Lv. 60 are reported in current guide data; check in game before spending.</div></div></div></div>`}
function collection(){const records=ANIIMO.filter(a=>owned(a.name));const l60=records.filter(a=>(state.collection[a.name].level||1)>=60).length;return `${title('PERSONAL VAULT / 005','My <em>collection.</em>','Track your actual roster, progression, held items and awakenings. Data stays in this browser until you export it.',`<button class="btn secondary" data-action="export">${icon('download',17)} Export JSON</button><button class="btn primary" data-action="import">${icon('upload',17)} Import JSON</button>`) }<div class="vault-stats"><div>${icon('layers',22)}<div><small>OWNED ANIIMO</small><strong>${records.length}<em> / ${ANIIMO.length}</em></strong></div></div><div>${icon('spark',22)}<div><small>LEVEL 60+</small><strong>${l60}</strong></div></div><div>${icon('target',22)}<div><small>TRACKED BUILDS</small><strong>${records.filter(a=>Object.keys(BUILDS).includes(a.name)).length}</strong></div></div><div>${icon('shield',22)}<div><small>STORAGE</small><strong class="storage-label">LOCAL ONLY</strong></div></div></div><div class="section-heading"><div><span class="section-kicker">YOUR UNITS</span><h2>Collection registry</h2></div>${button('Add Aniimo','aniidex','btn subtle','plus')}</div>${records.length?`<div class="collection-grid">${records.map(a=>{let p=state.collection[a.name];return `<div class="collection-card">${avatar(a,'lg')}<div class="collection-body"><div class="collection-title"><h3>${safe(a.name)}</h3>${elBadge(a.element,true)}</div>${p.form?`<div class="dex-collection-form">${safe(p.form)} form</div>`:''}<div class="collection-stats"><span>LEVEL <strong>${n(p.level,1,100,1)}</strong></span><span>CP <strong>${n(p.cp,0,999999,0).toLocaleString('en-US')}</strong></span><span>STAR <strong>${n(p.star,0,12,0)}</strong></span></div><div class="collection-actions"><button class="btn secondary" data-open="${safe(a.name)}">${icon('edit',16)} Edit profile</button><button class="icon-button" data-owned="${safe(a.name)}" title="Remove from collection">${icon('x',18)}</button></div></div></div>`}).join('')}</div>`:`<div class="empty-state">${icon('layers',30)}<h3>Your vault is empty</h3><p>Add Aniimo from the library and their builds will appear here.</p>${button('Browse library','aniidex','btn primary')}</div>`}<section class="data-actions"><div><span class="section-kicker">BACKUP & PORTABILITY</span><h3>Own your progression data</h3><p>Export anytime to move between your PC and phone. The app never uploads your collection to a server.</p></div><div><button class="btn secondary" data-action="export">${icon('download',16)} Download backup</button><button class="btn danger" data-action="reset">${icon('refresh',16)} Reset collection</button></div></section>`}
