const guideForForm=(species,form)=>{
 const guide=getBuild(species),published=!!BUILDS[species.name];
 const claim=String(guide.form||'').toLowerCase(),label=String(form.name||'Basic').toLowerCase();
 const matches=published&&(claim.includes(label)||(/basic or prismana/.test(claim)&&['basic','prismana'].includes(label)));
 return {guide,verified:matches,quality:matches?guide.quality:'Role-based starting point',note:matches?'Published build notes for this form; check current patch.':'No individually validated guide for this form. Suggestions below are role-aligned, not best-in-slot claims.'};
};
